// Recovered from the July 13 page-size Lantern session (regenerated by transcript replay).
const { JSDOM } = require("jsdom");
const fs = require("fs");

const html = fs.readFileSync(require("path").join(__dirname, "..", "src", "lantern.inner.html"), "utf8");
const dom = new JSDOM(html, {
  url: "http://localhost/",
  runScripts: "dangerously",
  pretendToBeVisual: true,
});
const { window } = dom;
const { document } = window;

let alerts = [];
window.alert = (m) => alerts.push(String(m));
window.confirm = () => true;
window.print = () => { window.__printed = (window.__printed || 0) + 1; };
window.URL.createObjectURL = () => "blob:fake";
window.URL.revokeObjectURL = () => {};
if (!window.HTMLElement.prototype.scrollIntoView)
  window.HTMLElement.prototype.scrollIntoView = () => {};

const results = [];
function check(name, ok, extra) {
  results.push([ok ? "PASS" : "FAIL", name, extra || ""]);
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

(async () => {
  // ---- boot ----
  await sleep(50);
  check("boot: shell started", !!document.querySelector(".bar"));
  check("boot: version at or past 1.5.1", /^1\.(5\.[1-9]|[6-9]\.|[1-9]\d\.)/.test(window.Lantern.version), window.Lantern.version);
  check("boot: hooks registered",
    (window.Lantern.writerEditHooks || []).length >= 1 &&
    (window.Lantern.writerSerialize || []).length >= 1 &&
    (window.Lantern.sheetEditHooks || []).length >= 3,
    `we=${(window.Lantern.writerEditHooks||[]).length} ws=${(window.Lantern.writerSerialize||[]).length} se=${(window.Lantern.sheetEditHooks||[]).length}`);

  // ---- writer ----
  window.location.hash = "writer";
  await sleep(30);
  document.querySelector("button.primary").click(); // + New document
  await sleep(30);
  const page = document.querySelector(".page[contenteditable]");
  check("writer: editor mounted", !!page);
  const tb = page && page.parentNode.firstChild;
  const selects = tb ? tb.querySelectorAll("select") : [];
  check("writer: paper controls added (size/orient/margin/zoom)", selects.length >= 4, `selects=${selects.length}`);
  check("writer: paged class + Letter width", page.classList.contains("lp-paged") && page.style.width === "816px", page.style.width);
  check("writer: @page rule live", [...document.querySelectorAll("style")].some(s => /@page\{size:8\.5in 11in;margin:1in;\}/.test(s.textContent)));

  // orientation change persists + swaps width
  const orientSel = [...selects].find(s => s.title === "Page orientation");
  orientSel.value = "l";
  orientSel.dispatchEvent(new window.Event("change", { bubbles: true }));
  await sleep(30);
  check("writer: landscape swaps width", page.style.width === "1056px", page.style.width);
  orientSel.value = "p";
  orientSel.dispatchEvent(new window.Event("change", { bubbles: true }));
  await sleep(30);

  // serializer strips gutters from saves and exports
  page.innerHTML = "<p>hello world</p><div class=\"lp-gap\" contenteditable=\"false\" data-label=\"Page 2\"></div><p>second page text</p>";
  page.dispatchEvent(new window.Event("input", { bubbles: true }));
  await sleep(900); // save debounce is 600ms
  const stored = JSON.parse(window.localStorage.getItem("lantern.writer.docs"));
  const wdoc = Object.values(stored)[0];
  check("writer: save strips lp-gap", wdoc.html.indexOf("lp-gap") < 0, wdoc.html);
  check("writer: paper settings persisted", wdoc.paper && wdoc.paper.size === "letter" && wdoc.paper.orient === "p", JSON.stringify(wdoc.paper));
  const ctl = document.createElement("div");
  ctl.innerHTML = wdoc.html; // gutters already stripped by the serializer
  const ctlRaw = ctl.innerText != null ? ctl.innerText : ctl.textContent;
  const ctlWords = ctlRaw.replace(/\s+/g, " ").trim().split(" ").length;
  check("writer: word count ignores gutters", wdoc.words === ctlWords, `words=${wdoc.words} ctl=${ctlWords}`);

  // continuous mode restores original styling
  const sizeSel = [...selects].find(s => s.title === "Paper size");
  sizeSel.value = "none";
  sizeSel.dispatchEvent(new window.Event("change", { bubbles: true }));
  await sleep(30);
  check("writer: continuous clears paged styling", !page.classList.contains("lp-paged") && page.style.width === "", page.style.width);
  sizeSel.value = "legal";
  sizeSel.dispatchEvent(new window.Event("change", { bubbles: true }));
  await sleep(900);

  // ---- sheet ----
  window.location.hash = "sheet";
  await sleep(30);
  document.querySelector("button.primary").click(); // + New sheet
  await sleep(30);
  const gridwrap = document.querySelector(".gridwrap");
  check("sheet: grid mounted", !!gridwrap && !!gridwrap.querySelector("table.grid"));
  const stb = gridwrap.parentNode.firstChild;
  const btns = [...stb.querySelectorAll("button")].map(b => b.textContent);
  check("sheet: hook buttons present (CSV x2, Page setup, Print)",
    btns.includes("Import CSV") && btns.includes("Export CSV") &&
    btns.includes("Page setup") && btns.includes("Print / PDF"), btns.join("|"));
  const panel = document.querySelector(".lp-shpanel");
  check("sheet: page setup panel mounted", !!panel);

  // enter values via the real UI path: click cell, type in fbar, Enter
  const fbar = document.querySelector(".fbar input");
  function put(ref, val) {
    gridwrap.querySelector(`td[data-ref="${ref}"]`).dispatchEvent(new window.MouseEvent("click", { bubbles: true }));
    fbar.value = val;
    fbar.dispatchEvent(new window.KeyboardEvent("keydown", { key: "Enter", bubbles: true, cancelable: true }));
  }
  put("A1", "part");   put("B1", "qty");
  put("A2", "bolt");   put("B2", "12");
  put("A3", "washer"); put("B3", "30");
  put("B4", "=SUM(B2:B3)");
  await sleep(30);
  check("sheet: formula computed", gridwrap.querySelector('td[data-ref="B4"]').textContent === "42",
    gridwrap.querySelector('td[data-ref="B4"]').textContent);

  // paper cfg persists per sheet
  const scaleIn = panel.querySelector("input[type=number]");
  scaleIn.value = "80";
  scaleIn.dispatchEvent(new window.Event("change", { bubbles: true }));
  await sleep(30);
  const sheetStore = JSON.parse(window.localStorage.getItem("lantern.sheet.docs"));
  const sdoc = Object.values(sheetStore)[0];
  check("sheet: paper cfg persisted (scale 80)", sdoc.paper && sdoc.paper.scale === 80, JSON.stringify(sdoc.paper));

  // print path: builds paginated print-area with repeated headers (synthetic
  // measure path in jsdom since offsetWidth is 0)
  [...stb.querySelectorAll("button")].find(b => b.textContent === "Print / PDF").click();
  await sleep(30);
  const prints = document.querySelectorAll(".lp-shprint");
  const cap = prints.length && prints[0].querySelector(".cap");
  const ths = prints.length ? [...prints[0].querySelectorAll("thead th")].map(t => t.textContent) : [];
  check("sheet: print built + window.print called", prints.length === 1 && window.__printed === 1);
  check("sheet: print caption + repeated headers", cap && /page 1 of 1/.test(cap.textContent) && ths.join(",") === ",A,B", `${cap && cap.textContent} | ${ths.join(",")}`);
  const b4cell = prints.length && [...prints[0].querySelectorAll("td")].map(t => t.textContent);
  check("sheet: print shows computed values", b4cell && b4cell.includes("42"), b4cell && b4cell.join("|"));
  await sleep(1600); // cleanup fallback timer
  check("sheet: print-area cleaned up", document.querySelectorAll(".lp-shprint").length === 0);

  // CSV export via the split-out module
  alerts = [];
  let dl = null;
  const origCreate = document.createElement.bind(document);
  // Lantern.download uses an <a download> click; intercept it
  const realDownload = window.Lantern.download;
  window.Lantern.download = (name, data, mime) => { dl = { name, data, mime }; };
  [...stb.querySelectorAll("button")].find(b => b.textContent === "Export CSV").click();
  await sleep(30);
  check("sheet: CSV export works from SHEET_CSV", dl && /42/.test(dl.data) && /bolt/.test(dl.data), dl && dl.data.replace(/\n/g, "\\n"));
  window.Lantern.download = realDownload;

  // empty-sheet guard on print
  window.location.hash = "";
  await sleep(30);
  window.location.hash = "sheet";
  await sleep(30);
  document.querySelector("button.primary").click();
  await sleep(30);
  alerts = [];
  const stb2 = document.querySelector(".gridwrap").parentNode.firstChild;
  [...stb2.querySelectorAll("button")].find(b => b.textContent === "Print / PDF").click();
  check("sheet: empty print guarded with alert", alerts.length === 1 && /empty/i.test(alerts[0]), alerts.join("|"));

  // guides appended to help
  check("guide: writer + sheet sections appended",
    window.Lantern.guide.has("writer") && window.Lantern.guide.has("sheet"));

  // ---- isolation: removing all hooks leaves core apps working ----
  window.Lantern.writerEditHooks.length = 0;
  window.Lantern.sheetEditHooks.length = 0;
  window.Lantern.writerSerialize.length = 0;
  window.location.hash = "writer";
  await sleep(30);
  document.querySelector("button.primary").click();
  await sleep(30);
  const page2 = document.querySelector(".page[contenteditable]");
  check("isolation: writer mounts with zero hooks", !!page2 && !page2.classList.contains("lp-paged"));
  window.location.hash = "sheet";
  await sleep(30);
  document.querySelector(".list .item .grow") && document.querySelector(".list .item .grow").click();
  await sleep(30);
  check("isolation: sheet mounts with zero hooks", !!document.querySelector(".gridwrap table.grid"));

  let fails = 0;
  for (const [st, name, extra] of results) {
    if (st === "FAIL") fails++;
    console.log(`${st}  ${name}${extra ? "   [" + extra + "]" : ""}`);
  }
  console.log(fails ? `\n${fails} FAILURES` : "\nALL PASS");
  process.exit(fails ? 1 : 0);
})().catch((e) => { console.error("SMOKE CRASH:", e); process.exit(2); });
